// Generated from the ByteRivet web generator (https://byterivet.com/test-files/).
// Do not edit by hand: run `npm run sync` after changing the site source.

'use strict';
/* ================================================================
   ByteRivet generation engine
   Every generator returns a Uint8Array of EXACTLY the requested
   length, while keeping the file structurally valid.
   ================================================================ */
const enc = new TextEncoder();
const S = s => enc.encode(s);
function cat(list){
  let n = 0; for (const a of list) n += a.length;
  const out = new Uint8Array(n); let o = 0;
  for (const a of list){ out.set(a, o); o += a.length; }
  return out;
}

/* ---- CRC32 (ZIP + PNG) ---- */
const CRCT = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++){
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  return t;
})();
function crcUpdate(c, b){
  for (let i = 0; i < b.length; i++) c = CRCT[(c ^ b[i]) & 0xFF] ^ (c >>> 8);
  return c >>> 0;
}
function crc32(...bufs){
  let c = 0xFFFFFFFF;
  for (const b of bufs) c = crcUpdate(c, b);
  return (c ^ 0xFFFFFFFF) >>> 0;
}
/* ---- Adler32, blocked for speed (zlib footer in PNG) ---- */
function adler32(buf){
  let a = 1, b = 0, i = 0, n = buf.length;
  while (i < n){
    const end = Math.min(i + 5552, n);
    for (; i < end; i++){ a += buf[i]; b += a; }
    a %= 65521; b %= 65521;
  }
  return ((b << 16) | a) >>> 0;
}

/* ---- deterministic filler: printable, non-uniform, fast ---- */
const PAT = (() => {
  const p = new Uint8Array(65536);
  let x = 0x2F6E2B1;
  for (let i = 0; i < p.length; i++){
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5; x >>>= 0;
    p[i] = 33 + (x % 90);           // printable ASCII range
  }
  return p;
})();
function fill(n, byte){
  const out = new Uint8Array(n);
  if (byte !== undefined){ out.fill(byte); return out; }
  let o = 0;
  while (o < n){ const c = Math.min(PAT.length, n - o); out.set(PAT.subarray(0, c), o); o += c; }
  return out;
}
/* ================= TEXT-BASED FORMATS ================= */
/* Build body rows until close to target, then pad exactly. */
function txtLike(target, kind){
  const MIN = { txt: 1, md: 40, html: 120, sql: 60, xml: 60, svg: 150, csv: 40, json: 30, bat: 111 }[kind] || 1;
  if (target < MIN) throw new Error('Minimum size for this format is ' + MIN + ' bytes.');

  /* CSV/JSON/the generic shells below all used to assemble one giant JS
     string (head + rows.join('') + padding) and encode it in one shot.
     That silently breaks around the 1 GiB mark: V8 caps string length a
     little under 2^30 characters, so a 1 GiB (1,073,741,824-byte) request
     threw "Invalid string length" with no page-visible error until this
     was caught by testing the new 1 GB/2 GB size tier for real. Every
     branch below now assembles a Uint8Array via cat()/fill() instead —
     the same byte-level padding approach every binary format already
     uses — so there is no string-length ceiling regardless of target. */
  if (kind === 'csv'){
    const head = S('id,first_name,last_name,email,country,signup_date,plan,mrr_usd\n');
    const rowBufs = [];
    let len = head.length;
    let i = 1;
    for (;;){
      const r = S(i + ',User' + i + ',Sample,user' + i + '@example.com,' +
        ['US','DE','TR','BR','JP','IN'][i % 6] + ',2024-0' + (1 + (i % 9)) + '-1' + (i % 9) +
        ',' + ['free','pro','team','scale'][i % 4] + ',' + ((i * 7) % 499) + '\n');
      if (len + r.length > target) break;
      rowBufs.push(r); len += r.length; i++;
      if (i > 4e6) break;
    }
    const out = cat([head, ...rowBufs]);
    const pad = target - out.length;
    if (pad <= 0) return out.subarray(0, target);
    return cat([out, fill(pad - 1, 0x78), S('\n')]);
  }

  if (kind === 'json'){
    const rowBufs = [];
    let i = 1, len = 0;
    const open = S('{"generator":"byterivet","records":[');
    const closeFixed = '],"_padding":"';
    for (;;){
      const r = S((rowBufs.length ? ',' : '') + '{"id":' + i + ',"name":"Record ' + i + '","active":' +
        (i % 2 ? 'true' : 'false') + ',"score":' + ((i * 13) % 100) + '}');
      if (open.length + len + r.length + closeFixed.length + 3 > target) break;
      rowBufs.push(r); len += r.length; i++;
      if (i > 4e6) break;
    }
    const body = cat([open, ...rowBufs, S(closeFixed)]);
    const pad = target - body.length - 2; // closing quote + brace
    return cat([body, fill(Math.max(0, pad), 0x78), S('"}')]);
  }

  const shells = {
    txt:  ['ByteRivet sample text file.\nGenerated in the browser at an exact byte size.\n\n', ''],
    md:   ['# Sample document\n\nGenerated by ByteRivet at an exact byte size.\n\n<!-- ', ' -->\n'],
    html: ['<!DOCTYPE html>\n<html lang="en">\n<head><meta charset="utf-8"><title>Sample</title></head>\n<body>\n<h1>Sample HTML file</h1>\n<p>Generated at an exact byte size.</p>\n<!-- ', ' -->\n</body>\n</html>\n'],
    sql:  ['-- Sample SQL dump\nCREATE TABLE users (id INT, email VARCHAR(255));\nINSERT INTO users VALUES (1, \'user1@example.com\');\n/* ', ' */\n'],
    xml:  ['<?xml version="1.0" encoding="UTF-8"?>\n<catalog>\n  <item id="1"><name>Sample</name></item>\n  <!-- ', ' -->\n</catalog>\n'],
    svg:  ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#0F1A17"/><circle cx="100" cy="100" r="60" fill="#00A388"/><!-- ', ' --></svg>'],
    /* Padding sits after `goto :eof`, a real batch idiom for "stop here" —
       cmd.exe never parses anything past it, so the padding bytes (which
       could contain anything) are 100% inert, the same trick PDF/DOCX use
       with unreferenced streams/parts. */
    bat:  ['@echo off\r\necho ByteRivet sample batch file.\r\necho Generated in the browser at an exact byte size.\r\ngoto :eof\r\n', '']
  };
  const [head, tail] = shells[kind] || shells.txt;
  const base = head.length + tail.length;
  if (kind === 'txt'){
    const h = shells.txt[0];
    return target <= h.length ? S(h.slice(0, target)) : cat([S(h), fill(target - h.length, 0x78)]);
  }
  if (target < base) throw new Error('Minimum size for this format is ' + base + ' bytes.');
  return cat([S(head), fill(target - base, 0x78), S(tail)]);
}

/* ================= PNG (hand-rolled, no canvas) ================= */
function pngChunk(type, data){
  const out = new Uint8Array(12 + data.length);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, data.length);
  out.set(S(type), 4);
  out.set(data, 8);
  dv.setUint32(8 + data.length, crc32(S(type), data));
  return out;
}
function pngPredict(w, h){
  const raw = h * (1 + w * 3);
  const blocks = Math.ceil(raw / 65535) || 1;
  const idat = 2 + blocks * 5 + raw + 4;
  return 8 + 25 + (12 + idat) + 12;      // sig + IHDR + IDAT + IEND
}
function makePNG(target, opt, prog){
  /* tEXt chunk floor: 12-byte chunk wrapper + the 8-byte "Comment\0"
     keyword actually written below (fill() only covers bytes ABOVE that
     fixed label, it can't shrink the label itself). This used to say 14
     (matching a shorter "C\0" keyword that was never what the code wrote),
     which let the w×h search accept combinations with only 0-7 spare
     bytes — too little for the real label, so the chunk silently grew and
     the file came out up to 6 bytes larger than requested with no error.
     Found by exhaustively generating every byte size near several
     boundaries and diffing the actual output length against the request. */
  const PADMIN = 20;
  const budget = target - PADMIN;
  let w = Math.max(8, Math.min(8192, opt.w | 0 || Math.round(Math.sqrt(target / 3.2))));
  let h = Math.max(8, Math.min(8192, opt.h | 0 || w));
  if (!opt.w || !opt.h){
    while (h > 8 && pngPredict(w, h) > budget) h = Math.floor(h * 0.92) || 8;
    while (pngPredict(w, h + 1) <= budget && h < 8192) h++;
    /* The pass above only searches h — for a real, measurable slice of
       target sizes (found by exhaustively testing every byte value near
       several size boundaries, not just near the format's stated minimum:
       ~6% near 1-10KB, ~1% near 100KB, ~0.4% near 1MB) the sqrt-derived w
       is already too wide for any h>=8 to fit, and this loop bottoms out
       still over budget. When both dimensions were left on auto, also
       shrink w and re-run the same h-search — repeated until it fits or
       w hits the floor, which (verified) always fits for any target at or
       above this format's true minimum. An explicitly requested width or
       height is left untouched, matching the format's own contract that a
       fixed dimension may legitimately fail with the message below. */
    if (!opt.w && !opt.h){
      while (pngPredict(w, h) > budget && w > 8){
        w = Math.max(8, Math.floor(w * 0.92) || 8);
        h = Math.min(8192, w);
        while (h > 8 && pngPredict(w, h) > budget) h = Math.floor(h * 0.92) || 8;
        while (pngPredict(w, h + 1) <= budget && h < 8192) h++;
      }
    }
  }
  if (pngPredict(w, h) > budget)
    throw new Error('Too small for a ' + w + '×' + h + ' PNG. Minimum is ' + pngPredict(w, h) + ' bytes, or leave the dimensions on auto.');

  /* raw scanlines: teal-to-ink gradient with subtle noise */
  const stride = 1 + w * 3;
  const raw = new Uint8Array(h * stride);
  for (let y = 0; y < h; y++){
    const o = y * stride; raw[o] = 0;
    const t = y / (h || 1);
    for (let x = 0; x < w; x++){
      const u = x / (w || 1), i = o + 1 + x * 3, n = (x * 7 + y * 13) & 15;
      raw[i]     = (15 + u * 20 + n) | 0;
      raw[i + 1] = (26 + t * 130 + n) | 0;
      raw[i + 2] = (23 + t * 110 + u * 25 + n) | 0;
    }
    if (prog && (y & 255) === 0) prog(y / h * 0.6);
  }

  /* zlib stream with stored (uncompressed) deflate blocks */
  const blocks = Math.ceil(raw.length / 65535) || 1;
  const z = new Uint8Array(2 + blocks * 5 + raw.length + 4);
  z[0] = 0x78; z[1] = 0x01;
  let zo = 2, ro = 0;
  for (let b = 0; b < blocks; b++){
    const len = Math.min(65535, raw.length - ro);
    z[zo++] = (b === blocks - 1) ? 1 : 0;
    z[zo++] = len & 255; z[zo++] = len >>> 8;
    z[zo++] = (~len) & 255; z[zo++] = (~len >>> 8) & 255;
    z.set(raw.subarray(ro, ro + len), zo);
    zo += len; ro += len;
  }
  const ad = adler32(raw);
  z[zo++] = (ad >>> 24) & 255; z[zo++] = (ad >>> 16) & 255; z[zo++] = (ad >>> 8) & 255; z[zo++] = ad & 255;
  if (prog) prog(0.85);

  const ihdr = new Uint8Array(13);
  const dv = new DataView(ihdr.buffer);
  dv.setUint32(0, w); dv.setUint32(4, h);
  ihdr[8] = 8; ihdr[9] = 2; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;   // 8-bit truecolour

  const sig  = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]);
  const core = cat([sig, pngChunk('IHDR', ihdr), pngChunk('IDAT', z)]);
  const pad  = target - core.length - 12 - 12;                          // IEND + tEXt overhead
  const text = cat([S('Comment\u0000'), fill(Math.max(0, pad - 8))]);
  return cat([core, pngChunk('tEXt', text), pngChunk('IEND', new Uint8Array(0))]);
}

/* ================= CANVAS FORMATS (JPG / WEBP) ================= */
async function canvasBytes(w, h, mime, q){
  if (typeof OffscreenCanvas === 'undefined')
    throw new Error('This browser cannot encode ' + mime + '. Try PNG instead.');
  const c = new OffscreenCanvas(w, h);
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, w, h);
  grad.addColorStop(0, '#0F1A17'); grad.addColorStop(1, '#00A388');
  g.fillStyle = grad; g.fillRect(0, 0, w, h);
  for (let i = 0; i < 240; i++){                     // texture keeps the encoder honest
    g.fillStyle = 'rgba(255,255,255,' + (0.02 + (i % 7) / 90) + ')';
    g.fillRect((i * 97) % w, (i * 53) % h, 40 + (i % 60), 40 + (i % 40));
  }
  g.fillStyle = '#EAF2EF'; g.font = 'bold ' + Math.max(12, Math.round(w / 12)) + 'px sans-serif';
  g.fillText(w + '×' + h, Math.round(w * 0.06), Math.round(h * 0.55));
  const blob = await c.convertToBlob({ type: mime, quality: q });
  return new Uint8Array(await blob.arrayBuffer());
}
async function makeJPEG(target, opt){
  let w = opt.w | 0 || 800, h = opt.h | 0 || 600, q = 0.85, base = null;
  for (let i = 0; i < 8; i++){
    base = await canvasBytes(w, h, 'image/jpeg', q);
    if (base.length <= target - 6) break;
    if (q > 0.2) { q -= 0.18; continue; }
    w = Math.max(16, Math.round(w * 0.7)); h = Math.max(16, Math.round(h * 0.7));
  }
  if (base.length > target - 6)
    throw new Error('Minimum JPEG size at these dimensions is about ' + (base.length + 6) + ' bytes.');
  /* pad with COM segments (max 65533 payload each), remainder after EOI */
  let need = target - base.length;
  const segs = [];
  while (need >= 5){
    const payload = Math.min(65533, need - 4);
    const seg = new Uint8Array(4 + payload);
    seg[0] = 0xFF; seg[1] = 0xFE;
    seg[2] = ((payload + 2) >> 8) & 255; seg[3] = (payload + 2) & 255;
    seg.set(fill(payload), 4);
    segs.push(seg); need -= seg.length;
  }
  return cat([base.subarray(0, 2), ...segs, base.subarray(2), fill(need)]);
}
async function makeWEBP(target, opt){
  let w = opt.w | 0 || 800, h = opt.h | 0 || 600, q = 0.85, base = null;
  for (let i = 0; i < 8; i++){
    base = await canvasBytes(w, h, 'image/webp', q);
    if (base.length <= target - 9) break;
    if (q > 0.2) { q -= 0.18; continue; }
    w = Math.max(16, Math.round(w * 0.7)); h = Math.max(16, Math.round(h * 0.7));
  }
  if (base.length > target - 9)
    throw new Error('Minimum WebP size at these dimensions is about ' + (base.length + 9) + ' bytes.');
  let need = target - base.length;                       // custom RIFF chunk absorbs it
  let payload = need - 8; if (payload & 1) payload--;    // chunks are even-padded
  const chunk = new Uint8Array(8 + payload + (payload & 1));
  chunk.set(S('PADD'), 0);
  new DataView(chunk.buffer).setUint32(4, payload, true);
  chunk.set(fill(payload), 8);
  const out = cat([base, chunk, fill(need - chunk.length)]);
  new DataView(out.buffer).setUint32(4, out.length - 8, true);   // fix RIFF size
  return out;
}

/* ================= PDF ================= */
function latin1(str){
  const out = new Uint8Array(str.length);
  for (let i = 0; i < str.length; i++) out[i] = str.charCodeAt(i) & 0xFF;
  return out;
}
/* The padding stream is written as raw bytes, never as a JS string —
   a 100 MB string here would cost seconds. */
function buildPDF(padLen){
  const content = 'BT /F1 22 Tf 62 760 Td (ByteRivet sample PDF) Tj ET\n' +
                  'BT /F1 11 Tf 62 736 Td (Generated in the browser at an exact byte size.) Tj ET\n';
  const objs = [
    '<</Type/Catalog/Pages 2 0 R>>',
    '<</Type/Pages/Kids[3 0 R]/Count 1>>',
    '<</Type/Page/Parent 2 0 R/MediaBox[0 0 595 842]/Resources<</Font<</F1 5 0 R>>>>/Contents 4 0 R>>',
    '<</Length ' + content.length + '>>stream\n' + content + 'endstream',
    '<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>'
  ];
  let head = '%PDF-1.7\n%\u00E2\u00E3\u00CF\u00D3\n';
  const off = [];
  for (let i = 0; i < objs.length; i++){
    off.push(head.length);
    head += (i + 1) + ' 0 obj\n' + objs[i] + '\nendobj\n';
  }
  off.push(head.length);
  head += '6 0 obj\n<</Length ' + padLen + '>>stream\n';        // padding stream opens here
  const mid = '\nendstream\nendobj\n';
  const xref = head.length + padLen + mid.length;               // byte offset of the xref keyword
  let tail = mid + 'xref\n0 7\n0000000000 65535 f \n';
  for (const o of off) tail += String(o).padStart(10, '0') + ' 00000 n \n';
  tail += 'trailer\n<</Size 7/Root 1 0 R>>\nstartxref\n' + xref + '\n%%EOF\n';
  return { head: head, tail: tail, len: head.length + padLen + tail.length };
}
function makePDF(target){
  const floor = buildPDF(0).len;
  if (target < floor) throw new Error('Minimum PDF size is ' + floor + ' bytes.');
  /* Converge on the padding length using string lengths only: writing the
     /Length value and the startxref offset can change their own digit count. */
  let pad = target - floor, parts = null;
  for (let i = 0; i < 8; i++){
    parts = buildPDF(pad);
    if (parts.len === target) break;
    pad = Math.max(0, pad + (target - parts.len));
  }
  const head = latin1(parts.head), tail = latin1(parts.tail);
  const out = new Uint8Array(target);                  // allocated exactly once
  out.set(head, 0);
  out.fill(0x58, head.length, target - tail.length);   // padding stream body
  out.set(tail, target - tail.length);
  return out;
}

/* ================= ZIP (store method) — also powers DOCX/XLSX ============ */
function makeZIP(entries){                     // [{name, data}]
  const locals = [], centrals = [];
  let offset = 0;
  for (const e of entries){
    const name = S(e.name), c = crc32(e.data);
    const lh = new Uint8Array(30 + name.length);
    const dv = new DataView(lh.buffer);
    dv.setUint32(0, 0x04034B50, true);
    dv.setUint16(4, 20, true); dv.setUint16(6, 0, true); dv.setUint16(8, 0, true);
    dv.setUint16(10, 0, true); dv.setUint16(12, 0x2821, true);      // fixed timestamp
    dv.setUint32(14, c, true);
    dv.setUint32(18, e.data.length, true); dv.setUint32(22, e.data.length, true);
    dv.setUint16(26, name.length, true); dv.setUint16(28, 0, true);
    lh.set(name, 30);
    locals.push(lh, e.data);

    const cd = new Uint8Array(46 + name.length);
    const cv = new DataView(cd.buffer);
    cv.setUint32(0, 0x02014B50, true);
    cv.setUint16(4, 20, true); cv.setUint16(6, 20, true);
    cv.setUint16(10, 0, true); cv.setUint16(12, 0, true); cv.setUint16(14, 0x2821, true);
    cv.setUint32(16, c, true);
    cv.setUint32(20, e.data.length, true); cv.setUint32(24, e.data.length, true);
    cv.setUint16(28, name.length, true);
    cv.setUint32(42, offset, true);
    cd.set(name, 46);
    centrals.push(cd);
    offset += lh.length + e.data.length;
  }
  const cdSize = centrals.reduce((n, c) => n + c.length, 0);
  const eocd = new Uint8Array(22);
  const ev = new DataView(eocd.buffer);
  ev.setUint32(0, 0x06054B50, true);
  ev.setUint16(8, entries.length, true); ev.setUint16(10, entries.length, true);
  ev.setUint32(12, cdSize, true); ev.setUint32(16, offset, true);
  return cat([...locals, ...centrals, eocd]);
}
function zipOverhead(name){ return 30 + name.length + 46 + name.length; }
function sizedZip(target, parts, padName){
  const fixed = makeZIP(parts).length;
  const padSize = target - fixed - zipOverhead(padName);
  if (padSize < 0)
    throw new Error('Minimum size for this format is ' + (fixed + zipOverhead(padName)) + ' bytes.');
  return makeZIP([...parts, { name: padName, data: fill(padSize) }]);
}
const OOXML_RELS = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';

function makeDOCX(target){
  const parts = [
    { name: '[Content_Types].xml', data: S('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="bin" ContentType="application/octet-stream"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>') },
    { name: '_rels/.rels', data: S(OOXML_RELS + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>') },
    { name: 'word/document.xml', data: S('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>ByteRivet sample DOCX</w:t></w:r></w:p><w:p><w:r><w:t>Generated in the browser at an exact byte size.</w:t></w:r></w:p></w:body></w:document>') }
  ];
  return sizedZip(target, parts, 'word/media/pad.bin');
}
function makeXLSX(target){
  const parts = [
    { name: '[Content_Types].xml', data: S('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="bin" ContentType="application/octet-stream"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>') },
    { name: '_rels/.rels', data: S(OOXML_RELS + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>') },
    { name: 'xl/workbook.xml', data: S('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Sheet1" sheetId="1" r:id="rId1"/></sheets></workbook>') },
    { name: 'xl/_rels/workbook.xml.rels', data: S(OOXML_RELS + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>') },
    { name: 'xl/worksheets/sheet1.xml', data: S('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>ByteRivet sample XLSX</t></is></c></row><row r="2"><c r="A2"><v>1048576</v></c></row></sheetData></worksheet>') }
  ];
  return sizedZip(target, parts, 'xl/media/pad.bin');
}
function makeZipFile(target, opt){
  const n = Math.max(1, Math.min(50, opt.files | 0 || 3));
  const parts = [];
  for (let i = 1; i < n; i++) parts.push({ name: 'sample-' + i + '.txt', data: S('ByteRivet sample file ' + i + '\n') });
  return sizedZip(target, parts, 'payload.bin');
}

/* ================= AUDIO / VIDEO ================= */
function makeWAV(target){
  if (target < 45) throw new Error('Minimum WAV size is 45 bytes.');
  const dataLen = target - 44;
  const out = new Uint8Array(target);
  const dv = new DataView(out.buffer);
  out.set(S('RIFF'), 0); dv.setUint32(4, target - 8, true); out.set(S('WAVE'), 8);
  out.set(S('fmt '), 12); dv.setUint32(16, 16, true);
  dv.setUint16(20, 1, true); dv.setUint16(22, 2, true);          // PCM, stereo
  dv.setUint32(24, 44100, true); dv.setUint32(28, 176400, true);
  dv.setUint16(32, 4, true); dv.setUint16(34, 16, true);
  out.set(S('data'), 36); dv.setUint32(40, dataLen, true);
  /* Quiet 220.5 Hz tone. 44100 / 220.5 = exactly 200 samples, so one
     period tiles seamlessly — no per-sample sin() over 100 MB. */
  const period = new Uint8Array(800);
  const pv = new DataView(period.buffer);
  for (let i = 0; i < 200; i++){
    const v = Math.round(Math.sin(i * 2 * Math.PI / 200) * 2600);
    pv.setInt16(i * 4, v, true); pv.setInt16(i * 4 + 2, v, true);
  }
  let o = 44;
  while (o < target){
    const c = Math.min(800, target - o);
    out.set(period.subarray(0, c), o); o += c;
  }
  return out;
}
function makeMP3(target){
  const FRAME = 417;                                    // 128 kbps, 44.1 kHz, MPEG-1 Layer III
  const MIN = 10 + FRAME;
  if (target < MIN) throw new Error('Minimum MP3 size is ' + MIN + ' bytes.');
  let frames = Math.floor((target - 10) / FRAME);
  let tagPad = target - 10 - frames * FRAME;
  const out = new Uint8Array(target);
  out.set(S('ID3'), 0); out[3] = 3; out[4] = 0; out[5] = 0;
  out[6] = (tagPad >>> 21) & 0x7F; out[7] = (tagPad >>> 14) & 0x7F;
  out[8] = (tagPad >>> 7) & 0x7F;  out[9] = tagPad & 0x7F;        // syncsafe size
  let o = 10 + tagPad;
  for (let f = 0; f < frames; f++){
    out[o] = 0xFF; out[o + 1] = 0xFB; out[o + 2] = 0x90; out[o + 3] = 0x00;
    o += FRAME;
  }
  return out;
}
function makeMP4(target){
  const MIN = 32 + 8 + 8;
  if (target < MIN) throw new Error('Minimum MP4 size is ' + MIN + ' bytes.');
  const out = new Uint8Array(target);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, 32); out.set(S('ftyp'), 4);
  out.set(S('isom'), 8); dv.setUint32(12, 512);
  out.set(S('isomiso2avc1mp41'), 16);
  const freeLen = target - 32 - 8;
  dv.setUint32(32, freeLen + 8); out.set(S('free'), 36);
  out.set(fill(freeLen), 40);
  return out;
}

/* ================= EXE ================= */
/* A genuine, well-formed MS-DOS + PE header (the same bytes libmagic/`file`,
   antivirus engines and upload validators check to identify "PE32
   executable") with the standard "This program cannot be run in DOS mode"
   stub every real .exe carries. Deliberately declares zero sections and a
   null entry point, so a real Windows loader refuses it cleanly ("not a
   valid Win32 application") instead of ever executing a single instruction
   — this generator never ships runnable code. Padding after the header is
   inert for the same reason nothing beyond SizeOfImage/SizeOfHeaders is
   ever read by the loader. */
function makeEXE(target){
  const DOS_STUB = new Uint8Array([0x0e,0x1f,0xba,0x0e,0x00,0xb4,0x09,0xcd,0x21,0xb8,0x01,0x4c,0xcd,0x21]);
  const DOS_MSG = S('This program cannot be run in DOS mode.\r\r\n$');
  const stub = cat([DOS_STUB, DOS_MSG]);
  const stubPad = (8 - (64 + stub.length) % 8) % 8;
  const peOffset = 64 + stub.length + stubPad;

  const dos = new Uint8Array(64);
  const ddv = new DataView(dos.buffer);
  dos.set(S('MZ'), 0);
  ddv.setUint16(2, 0x90, true); ddv.setUint16(4, 3, true); ddv.setUint16(8, 4, true);
  ddv.setUint16(12, 0xFFFF, true); ddv.setUint16(16, 0xB8, true); ddv.setUint16(24, 0x40, true);
  ddv.setUint32(60, peOffset, true);

  const coff = new Uint8Array(20);
  const cdv = new DataView(coff.buffer);
  cdv.setUint16(0, 0x014c, true);   // Machine: I386
  cdv.setUint16(2, 0, true);        // NumberOfSections
  cdv.setUint16(16, 224, true);     // SizeOfOptionalHeader (PE32)
  cdv.setUint16(18, 0x0102, true);  // Characteristics: EXECUTABLE_IMAGE | 32BIT_MACHINE

  const opt = new Uint8Array(224);
  const odv = new DataView(opt.buffer);
  odv.setUint16(0, 0x10b, true);        // Magic: PE32
  opt[2] = 14;                          // MajorLinkerVersion
  odv.setUint32(28, 0x400000, true);    // ImageBase
  odv.setUint32(32, 0x1000, true);      // SectionAlignment
  odv.setUint32(36, 0x200, true);       // FileAlignment
  odv.setUint16(40, 6, true);           // MajorOSVersion
  odv.setUint16(48, 6, true);           // MajorSubsystemVersion
  const headersRaw = peOffset + 4 + coff.length + opt.length;
  const sizeOfHeaders = Math.ceil(headersRaw / 0x200) * 0x200;
  odv.setUint32(56, sizeOfHeaders, true); // SizeOfImage (no sections beyond headers)
  odv.setUint32(60, sizeOfHeaders, true); // SizeOfHeaders
  odv.setUint16(68, 3, true);           // Subsystem: CUI
  odv.setUint32(72, 0x100000, true);    // SizeOfStackReserve
  odv.setUint32(76, 0x1000, true);      // SizeOfStackCommit
  odv.setUint32(80, 0x100000, true);    // SizeOfHeapReserve
  odv.setUint32(84, 0x1000, true);      // SizeOfHeapCommit
  odv.setUint32(92, 16, true);          // NumberOfRvaAndSizes

  const head = cat([dos, stub, fill(stubPad, 0), S('PE\0\0'), coff, opt]);
  const headPadded = cat([head, fill(sizeOfHeaders - head.length, 0)]);
  if (target < headPadded.length) throw new Error('Minimum EXE size is ' + headPadded.length + ' bytes.');
  return cat([headPadded, fill(target - headPadded.length, 0)]);
}

/* ================= ISO (ISO 9660 / ECMA-119) ================= */
/* A real, mountable disc image: 16-sector system area, Primary Volume
   Descriptor, terminator, L/M path tables, one root directory extent, and
   a single README.TXT file whose data IS the padding — so the image opens
   in Explorer/Finder/7-Zip and shows one real, readable file, the same
   "genuinely valid, not a placeholder" bar every other format here holds. */
function isoBothEndian32(n){ const b = new Uint8Array(8); const dv = new DataView(b.buffer); dv.setUint32(0, n, true); dv.setUint32(4, n, false); return b; }
function isoBothEndian16(n){ const b = new Uint8Array(4); const dv = new DataView(b.buffer); dv.setUint16(0, n, true); dv.setUint16(2, n, false); return b; }
function isoPad(str, len){ const out = new Uint8Array(len); out.fill(0x20); const s = S(str); out.set(s.subarray(0, Math.min(s.length, len)), 0); return out; }
function isoVolDate(){
  const d = new Date();
  const s = String(d.getUTCFullYear()).padStart(4,'0') + String(d.getUTCMonth()+1).padStart(2,'0') +
    String(d.getUTCDate()).padStart(2,'0') + String(d.getUTCHours()).padStart(2,'0') +
    String(d.getUTCMinutes()).padStart(2,'0') + String(d.getUTCSeconds()).padStart(2,'0') + '00';
  const out = new Uint8Array(17); out.fill(0x30); out.set(S(s), 0); out[16] = 0;
  return out;
}
function isoDirRecordDate(){
  const d = new Date();
  return new Uint8Array([d.getUTCFullYear()-1900, d.getUTCMonth()+1, d.getUTCDate(), d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds(), 0]);
}
function isoDirRecord(extent, length, flags, identifier){
  const id = S(identifier);
  const recLen = 33 + id.length + (id.length % 2 === 0 ? 1 : 0);
  const r = new Uint8Array(recLen);
  const dv = new DataView(r.buffer);
  r[0] = recLen; r[1] = 0;
  r.set(isoBothEndian32(extent), 2);
  r.set(isoBothEndian32(length), 10);
  r.set(isoDirRecordDate(), 18);
  r[25] = flags; r[26] = 0; r[27] = 0;
  r.set(isoBothEndian16(1), 28);
  r[32] = id.length;
  r.set(id, 33);
  return r;
}
function makeISO(target){
  const BLK = 2048, STRUCT_BLOCKS = 21; // 0-15 system, 16 PVD, 17 term, 18 L-path, 19 M-path, 20 root dir
  const structBytes = STRUCT_BLOCKS * BLK;
  if (target < structBytes + 1) throw new Error('Minimum ISO size is ' + (structBytes + 1) + ' bytes.');

  const fileLBA = STRUCT_BLOCKS;
  const fileLen = target - structBytes;
  const totalBlocks = STRUCT_BLOCKS + Math.ceil(fileLen / BLK);

  const rootRec = isoDirRecord(20, BLK, 2, '\x00');
  const dot     = isoDirRecord(20, BLK, 2, '\x00');
  const dotdot  = isoDirRecord(20, BLK, 2, '\x01');
  const fileRec = isoDirRecord(fileLBA, fileLen, 0, 'README.TXT;1');
  const rootDirBlock = new Uint8Array(BLK);
  rootDirBlock.set(cat([dot, dotdot, fileRec]), 0);

  // Path tables: single entry (root), directory id = one 0x00 byte
  function pathTable(be){
    const b = new Uint8Array(9);
    const dv = new DataView(b.buffer);
    b[0] = 1; b[1] = 0;
    dv.setUint32(2, 20, !be);
    dv.setUint16(6, 1, !be);
    b[8] = 0;
    return b;
  }
  const lBlock = new Uint8Array(BLK); lBlock.set(pathTable(false), 0);
  const mBlock = new Uint8Array(BLK); mBlock.set(pathTable(true), 0);
  const pathTableSize = 9;

  const pvd = new Uint8Array(BLK);
  const pdv = new DataView(pvd.buffer);
  pvd[0] = 1; pvd.set(S('CD001'), 1); pvd[6] = 1;
  pvd.set(isoPad('BYTERIVET', 32), 8);
  pvd.set(isoPad('BYTERIVET_SAMPLE', 32), 40);
  pvd.set(isoBothEndian32(totalBlocks), 80);
  pvd.set(isoBothEndian16(1), 120);
  pvd.set(isoBothEndian16(1), 124);
  pvd.set(isoBothEndian16(BLK), 128);
  pvd.set(isoBothEndian32(pathTableSize), 132);
  pdv.setUint32(140, 18, true);   // type L path table LBA
  pdv.setUint32(144, 0, true);
  pdv.setUint32(148, 19, false);  // type M path table LBA
  pdv.setUint32(152, 0, false);
  pvd.set(rootRec, 156);
  pvd.set(isoPad('BYTERIVET', 128), 190);
  pvd.set(isoPad('BYTERIVET', 128), 318);
  pvd.set(isoPad('BYTERIVET.COM', 128), 446);
  pvd.set(isoPad('BYTERIVET GENERATOR', 128), 574);
  pvd.set(isoVolDate(), 813);
  pvd.set(isoVolDate(), 830);
  const expDate = new Uint8Array(17); expDate.fill(0x30); expDate[16] = 0;
  pvd.set(expDate, 847);
  pvd.set(isoVolDate(), 864);
  pvd[881] = 1; // file_structure_version

  const term = new Uint8Array(BLK);
  term[0] = 255; term.set(S('CD001'), 1); term[6] = 1;

  const head = cat([new Uint8Array(16 * BLK), pvd, term, lBlock, mBlock, rootDirBlock]);
  const msg = S('ByteRivet sample ISO 9660 disc image.\r\nGenerated in the browser at an exact byte size.\r\n');
  const fileData = new Uint8Array(fileLen);
  fileData.set(msg.subarray(0, Math.min(msg.length, fileLen)), 0);
  if (fileLen > msg.length) fileData.set(fill(fileLen - msg.length), msg.length);
  return cat([head, fileData]);
}

/* ================= REGISTRY ================= */
async function generate(fmt, target, opt, prog){
  switch (fmt){
    case 'pdf':  return makePDF(target);
    case 'png':  return makePNG(target, opt, prog);
    case 'jpg':  return await makeJPEG(target, opt);
    case 'webp': return await makeWEBP(target, opt);
    case 'svg':  return txtLike(target, 'svg');
    case 'txt':  return txtLike(target, 'txt');
    case 'csv':  return txtLike(target, 'csv');
    case 'json': return txtLike(target, 'json');
    case 'xml':  return txtLike(target, 'xml');
    case 'html': return txtLike(target, 'html');
    case 'sql':  return txtLike(target, 'sql');
    case 'md':   return txtLike(target, 'md');
    case 'bat':  return txtLike(target, 'bat');
    case 'zip':  return makeZipFile(target, opt);
    case 'docx': return makeDOCX(target);
    case 'xlsx': return makeXLSX(target);
    case 'wav':  return makeWAV(target);
    case 'mp3':  return makeMP3(target);
    case 'mp4':  return makeMP4(target);
    case 'bin':  return fill(target);
    case 'exe':  return makeEXE(target);
    case 'iso':  return makeISO(target);
    default: throw new Error('Unknown format: ' + fmt);
  }
}

export const FORMATS = ['pdf','png','svg','txt','csv','json','xml','html','sql','md','bat','zip','docx','xlsx','wav','mp3','mp4','bin','exe','iso'];
export { generate };
